NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'James'

CHAPTERS = {
    1: {
        1: 'Jakob, služabnik Boga in Gospoda Jezusa Kristusa, dvanajsterim rodovom, ki so razkropljeni naokoli, pozdrav.',
        2: 'Moji bratje, kadar zapadate v številne skušnjave, štejte to [za] veliko veselje,',
        3: 'ker veste to, da preizkušenost vaše vere ustvarja potrpežljivost.',
        4: 'Toda naj ima potrpežljivost svoje popolno delo, da boste lahko popolni in celotni, [da vam] ničesar ne manjka.',
        5: 'Če [pa] komu izmed vas manjka modrosti, naj prosi od Boga, ki velikodušno daje vsem ljudem in ne očita; in dana mu bo.',
        6: 'Toda prosi naj v veri niti malo omahujoč. Kajti kdor omahuje, je podoben morskemu valu, [ki ga] žene veter in ga premetava.',
        7: 'Kajti tak človek naj ne misli, da bo karkoli prejel od Gospoda.',
        8: 'Človek dvojnih misli je nestanoviten na vseh svojih poteh.',
        9: 'Naj se brat nizkega položaja veseli v tem, da je povišan;',
        10: 'toda bogat v tem, da je ponižan, ker bo minil kakor cvet na travi.',
        11: 'Kajti takoj, ko sonce vzide z žgočo vročino, to izsuši travo in njen cvet pade in lepota njenega videza propade; tako bo tudi bogataš zbledel na svojih poteh.',
        12: 'Blagoslovljen je človek, ki preizkušnjo vzdrži; kajti ko je preizkušen, bo prejel krono življenja, ki jo je Gospod obljubil tistim, ki ga ljubijo.',
        13: 'Naj noben človek, ko je skušan, ne reče: »Skušan sem od Boga,« kajti Bog ne more biti skušan z zlom niti sam nikogar ne skuša.',
        14: 'Toda vsak je skušan, ko je odtegnjen s svojimi lastnimi poželenji in premamljen.',
        15: 'Ko je potem poželenje spočeto, rojeva greh. Greh pa, ko je dovršen, rojeva smrt.',
        16: 'Ne motite se, moji ljubljeni bratje.',
        17: 'Vsak dober dar in vsako popolno darilo je od zgoraj in prihaja dol od Očeta svetil, s katerim ni nestanovitnosti niti sence obračanja.',
        18: 'Po svoji lastni volji nas je zaplodil z besedo resnice, da naj bi bili mi nekako prvenci njegovih ustvarjenih bitij.',
        19: 'Zatorej, moji ljubljeni bratje, naj bo vsak človek hiter za poslušanje, počasen za govorjenje, počasen za bes;',
        20: 'kajti človekov bes ne uresničuje Božje pravičnosti.',
        21: 'Zatorej dajte proč vso umazanost in odvečno porednost ter s krotkostjo sprejmite vcepljeno besedo, ki je zmožna rešiti vaše duše.',
        22: 'Toda bodite uresničevalci besede in ne le poslušalci, ki sami sebe varajo.',
        23: 'Kajti če je kdorkoli poslušalec besede, ne pa uresničevalec, je podoben človeku, ki svoj naraven obraz ogleduje v zrcalu;',
        24: 'kajti gleda sebe in gre svojo pot ter nemudoma pozabi, kakšne vrste človek je bil.',
        25: 'Toda kdorkoli gleda v popolno postavo svobode in ostaja v njej, ni pozabljiv poslušalec, temveč izvrševalec dela, bo ta človek blagoslovljen v svojem dejanju.',
        26: 'Če je katerikoli človek med vami videti religiozen, pa ne brzda svojega jezika, temveč zavaja svoje lastno srce, je bogoslužje tega človeka prazno.',
        27: 'Čisto in neomadeževano bogoslužje pred Bogom in Očetom je to: »Obiskovati osirotele in vdove v njihovi stiski ter se ohraniti neomadeževanega od sveta.«',
    },
    2: {
        1: 'Moji bratje, vere našega Gospoda Jezusa Kristusa, Gospoda slave, ne imejte z oziranjem na osebe.',
        2: 'Kajti če pride v vaš zbor mož z zlatim prstanom in čedno obleko, pride pa tudi revež v grdem oblačilu;',
        3: 'in se ozirate k tistemu, ki nosi elegantno oblačilo ter mu rečete: »Sédi tukaj na dobro mesto;« revnemu pa rečete: »Stoj tukaj ali sédi tukaj pod mojo pručko.«',
        4: 'Mar niste potem v sebi pristranski in ste postali sodniki s hudobnimi mislimi?',
        5: 'Poslušajte, moji ljubljeni bratje: »Ali ni Bog izbral revnih tega sveta, bogatih v veri in dedičev kraljestva, ki ga je obljubil tem, ki ga ljubijo?«',
        6: 'Toda vi ste prezirali revnega. Ali vas ne zatirajo bogataši in vas vlečejo pred sodne stole?',
        7: 'Ali ne preklinjajo oni tega vrednega imena, po katerem ste imenovani?',
        8: 'Če izpolnite kraljevo postavo glede pisma: »Svojega bližnjega boš ljubil kakor samega sebe,« delate pravilno.',
        9: 'Toda če se ozirate na osebe, storite greh in ste po postavi pograjani kot prestopniki.',
        10: 'Kajti kdorkoli se bo držal celotne postave in se vendar prekrši v eni točki, je kriv vseh.',
        11: 'Kajti kdor je rekel: »Ne počni zakonolomstva,« je rekel tudi: »Ne ubijaj.« Torej če ne počneš zakonolomstva, vendar če ubijaš, si postal prestopnik postave.',
        12: 'Tako govorite in tako delajte kakor tisti, ki bodo sojeni po postavi svobode.',
        13: 'Kajti tisti, ki ni pokazal nobenega usmiljenja, bo sodbo prejel brez usmiljenja; in usmiljenje se razveseljuje zoper sodbo.',
        14: 'Kaj to koristi, moji bratje, četudi človek reče, [da] ima vero, nima pa del? Mar ga lahko vera reši?',
        15: 'Če sta brat ali sestra naga in brez dnevne hrane,',
        16: 'in jima kdo izmed vas reče: »Odidita v miru, bodita ogreta in nasičena;« čeprav jima ne daste teh stvari, ki so potrebne telesu; kaj to koristi?',
        17: 'Prav tako vera, če ta nima del, je sama zase mrtva.',
        18: 'Da, človek lahko reče: »Ti imaš vero, jaz pa imam dela. Pokaži mi svojo vero brez svojih del in pokazal ti bom svojo vero s svojimi deli.',
        19: 'Ti veruješ, da obstaja en Bog; pravilno ravnaš. Tudi hudiči verujejo in trepetajo.«',
        20: 'Toda ali hočeš spoznati, oh prazni človek, da je vera brez del mrtva?',
        21: 'Mar ni bil naš oče Abraham opravičen z deli, ko je na oltarju daroval svojega sina Izaka?',
        22: 'Vidiš, kako je vera sodelovala z njegovimi deli in je vera z deli postala popolna?',
        23: 'In izpolnjeno je bilo pismo, ki pravi: ›Abraham je veroval Bogu in to mu je bilo pripisano v pravičnost;‹ in imenovan je bil: ›Prijatelj Boga.‹',
        24: 'Vidite torej kako, da je človek opravičen z deli in ne samo iz vere.',
        25: 'Ali ni bila prav tako tudi pocestnica Rahába opravičena z deli, ko je sprejela poslanca in ju odposlala [po] drugi poti?',
        26: 'Kajti kakor je telo brez duha mrtvo, tako je tudi vera brez del mrtva.',
    },
    3: {
        1: 'Moji bratje, ne bodite mnogi učitelji, ker veste, da bomo prejeli večjo obsodbo.',
        2: 'Kajti v mnogih stvareh vsi grešimo. Če katerikoli človek ne greši z besedo, je isti popoln mož in tudi zmožen obrzdati celotno telo.',
        3: 'Glejte, konjem v usta dajemo žvale, da nas lahko ubogajo in obračamo njihovo celotno telo.',
        4: '§ Glejte tudi ladje, katere, čeprav so tako velike in jih ženejo kruti vetrovi, se vendar obračajo z zelo majhnim krmilom, kamorkoli krmar hoče.',
        5: 'Prav tako je jezik majhen ud, pa se baha [z] velikimi stvarmi. Glejte, kako veliko stvar prižge majhen ogenj!',
        6: 'In jezik je ogenj, svet krivičnosti. Tako je jezik med našimi udi, da omadežuje celotno telo in razvnema zakon narave; in ta je vžgan iz pekla.',
        7: 'Kajti vsaka vrsta, od živali in od ptic in od kač in od stvari v morju, je ukrotljiva in je bila ukročena od človeštva,',
        8: 'toda jezika ne more ukrotiti noben človek; je neukrotljivo zlo, polno smrtonosnega strupa.',
        9: 'Z njim blagoslavljamo Boga, celó Očeta; in z njim preklinjamo ljudi, ki so ustvarjeni po Božji podobnosti.',
        10: 'Iz istih ust izvirata blagoslavljanje in preklinjanje. Moji bratje, te stvari ne smejo biti takšne.',
        11: 'Mar daje studenec na istem mestu sladko in grenko vodo?',
        12: 'Ali lahko figovo drevo, moji bratje, rodi olive? Ali trta fige? Tako noben studenec ne more dajati obeh, slane in sladke vode.',
        13: 'Kdo je med vami moder človek in opremljen s spoznanjem? Naj s krotkostjo modrosti kaže dobro vedênje svojih del.',
        14: 'Toda če imate v svojih srcih grenko zavist in prepir, se ne ponašajte in ne lažite zoper resnico.',
        15: 'Ta modrost se ne spušča od zgoraj, temveč je zemeljska, čutna, vražja.',
        16: 'Kajti kjer sta zavist in prepir, tam je zmešnjava in vsako hudobno delo.',
        17: 'Toda modrost, ki je od zgoraj, je najprej čista, potem mirna, nežna in lahka za ravnanje, polna usmiljenja in dobrih sadov, brez pristranskosti in brez hinavščine.',
        18: 'In sad pravičnosti sejejo v miru tisti, ki delajo mir.',
    },
    4: {
        1: 'Od kod prihajajo med vami vojne in boji? Ali ne pridejo od tod, celó iz vaših poželenj, ki se vojskujejo v vaših udih?',
        2: 'Vi hlepite, pa nimate. Ubijate in želite imeti, pa ne morete doseči. Bojujete se in vojskujete, vendar nimate, ker ne prosite.',
        3: 'Prosite, pa ne prejmete, ker prosite neprimerno, da bi to porabili za svoja poželenja.',
        4: 'Vi zakonolomci in zakonolomke ali ne veste, da je prijateljstvo s svetom sovraštvo do Boga? Kdorkoli bo torej prijatelj sveta, postane Božji sovražnik.',
        5: '§ Ali mislite, da pismo zaman pravi: »Duh, ki prebiva v nas, hrepeni do zavisti?«',
        6: 'Toda on daje več milosti. Zatorej pravi: »Bog se ponosnim upira, toda ponižnim daje milost.«',
        7: 'Podvrzite se torej Bogu. Uprite se hudiču in bo od vas pobegnil.',
        8: 'Približajte se Bogu in se vam bo približal. Očistite si svoje roke, vi grešniki; in očistite svoja srca, vi, [ki ste] dvojnih misli.',
        9: 'Bodite užaloščeni in žalujte ter jokajte. Naj bo vaš smeh obrnjen v žalovanje in vaša radost v potrtost.',
        10: 'Ponižajte se v Gospodovih očeh in vas bo povišal.',
        11: 'Bratje, drug o drugem ne govorite hudobno. Kdor o svojem bratu govori hudobno in svojega brata sodi, govori hudobno o postavi in sodi postavo. Toda če sodiš postavo, nisi uresničevalec postave, temveč sodnik.',
        12: '§ En zakonodajalec je, ki je zmožen rešiti in uničiti. Kdo si ti, da sodiš drugega?',
        13: 'Pojdite torej, vi, ki pravite: »Danes ali jutri bomo šli v to mesto in tam ostali eno leto in kupovali in prodajali ter zaslužili dobiček;«',
        14: 'medtem ko ne veste, kaj bo jutri. Kajti kaj je vaše življenje? Je celó meglica, ki se za kratek čas prikaže in potem izgine proč.',
        15: 'Kajti takó morate reči: »Če Gospod hoče, bomo živeli in delali to ali ono.«',
        16: 'Toda sedaj se razveseljujete v svojih bahanjih. Vsako takšno razveseljevanje je zlo.',
        17: 'Torej tistemu, ki zna delati dobro, pa tega ne dela, mu je to [v] greh.',
    },
    5: {
        1: 'Pojdite torej, vi bogataši, jokajte in tulite zaradi svojih bed, ki bodo prišle nad vas.',
        2: 'Vaša bogastva so pokvarjena in vaše obleke so požrte od moljev.',
        3: 'Vaše zlato in srebro je postalo zarjavelo; in njuna rja bo priča zoper vas in bo razjedla vaše meso, kakor bi bila ogenj. Nakopičili ste skupaj zaklad za poslednje dni.',
        4: 'Glejte, plačilo delavcev, ki so poželi vaša polja, ki ste si jih pridržali s sleparstvom, kriči. In kriki teh, ki so poželi, so vstopili v ušesa Gospoda nad vojskami.',
        5: 'Na zemlji ste živeli v užitku in bili polteni; svoja srca ste redili kakor za dan zakola.',
        6: 'Obsodili in ubili ste pravičnega; in se vam ne upira.',
        7: 'Bodite torej potrpežljivi, bratje, do Gospodovega prihoda. Glejte, poljedelec pričakuje dragocen sad zemlje in ima za to veliko potrpežljivost, dokler ne prejme zgodnjega in poznega dežja.',
        8: 'Bodite tudi vi potrpežljivi. Utrdite svoja srca, kajti Gospodov prihod se približuje.',
        9: 'Ne godrnjajte drug proti drugemu, bratje, da ne bi bili obsojeni. Glejte, sodnik stoji pred vrati.',
        10: 'Moji bratje, za zgled prenašanja stiske in potrpežljivosti vzemite preroke, ki so govorili v Gospodovem imenu.',
        11: 'Glejte, mi štejemo za srečne te, ki vztrajajo. Slišali ste o Jobovi potrpežljivosti in videli Gospodov konec; da je Gospod zelo sočuten in nežno usmiljen.',
        12: 'Toda nad vsemi stvarmi, moji bratje, ne prisegajte, niti pri nebu, niti pri zemlji, niti s kako drugo prisego. Temveč vaš »da« naj bo »da« in vaš »ne« [naj bo] »ne«, da ne zapadete v obsodbo.',
        13: '§ Ali je kdo med vami v stiski? Naj moli. Ali je kdo vesel? Naj prepeva psalme.',
        14: 'Je kdo med vami bolan? Naj pokliče starešine cerkve in naj nad njim molijo ter ga v Gospodovem imenu mazilijo z oljem.',
        15: 'In molitev vere bo rešila bolnika in Gospod ga bo vzdignil; in če je storil grehe, mu bodo odpuščeni.',
        16: '§ Drug drugemu priznavajte svoje napake in molíte drug za drugega, da boste lahko ozdravljeni. Veliko koristi energična, goreča molitev pravičnega.',
        17: 'Elija je bil človek, podvržen podobnim strastem, kakor smo mi in je iskreno molil, da ne bi deževalo. In na zemljo ni deževalo v obdobju treh let in šestih mesecev.',
        18: 'In ponovno je molil in nebo je dalo dež in zemlja je obrodila svoj sad.',
        19: 'Bratje, če kdo izmed vas zaide od resnice in ga nekdo spreobrne,',
        20: 'naj ta ve, da kdor je grešnika spreobrnil od zmote njegove poti, bo rešil dušo pred smrtjo in zakril množico grehov.',
    },
}
